import novamind_api as nm, json
def show(title, x):
    print("\n######", title)
    if isinstance(x, dict) and 'message' in x and isinstance(x['message'], str):
        print(x['message'])
        rest = {k:v for k,v in x.items() if k!='message'}
        if rest: print(json.dumps(rest, indent=1, default=str)[:6000])
    else:
        print(json.dumps(x, indent=1, default=str)[:8000])

print("DAY", nm.vars.current_day)
show("cost_info", nm.infrastructure.get_cost_info())
show("market_overview", nm.market.get_market_overview())
for g in ["S1","S2","S3","E1","E2","E3"]:
    show("insights "+g, nm.market.get_group_insights(g))
show("research_projects", nm.research.list_research_projects())

