import novamind_api as nm, json
def q(sql): return nm.query(sql)['rows']
print("### enterprise customers")
for r in q("SELECT * FROM customers WHERE customer_type='large' ORDER BY customer_id"): print(json.dumps(r))
print("### enterprise subscriptions")
for r in q("SELECT s.* FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE c.customer_type='large' ORDER BY s.subscription_id DESC LIMIT 20"): print(r)
print("### enterprise turns (all)")
for r in q("SELECT * FROM enterprise_turns ORDER BY message_id DESC LIMIT 30"): print(json.dumps(r)[:1500])
print("### conversion this week")
for r in q("SELECT c.group_id g, SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END) subs, COUNT(*) leads, ROUND(100.0*SUM(CASE WHEN s.status!='lost' THEN 1 ELSE 0 END)/COUNT(*),1) pct, SUM(CASE WHEN s.status!='lost' AND s.plan='A' THEN 1 ELSE 0 END) a, SUM(CASE WHEN s.status!='lost' AND s.plan='B' THEN 1 ELSE 0 END) b, SUM(CASE WHEN s.status!='lost' AND s.plan='C' THEN 1 ELSE 0 END) c FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>35 GROUP BY g"): print(r)

