import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:1500])
    except Exception as e:
        print("ERR", label, "->", e)
def q(sql): return nm.query(sql)['rows']
# open threads needing a response: latest turn sender in (system turn0, customer)
rows = q("""SELECT e.thread_id, e.customer_id, e.turn_number, e.sender, c.group_id
FROM enterprise_turns e JOIN customers c ON c.customer_id=e.customer_id
WHERE e.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)
AND e.thread_id NOT IN (SELECT thread_id FROM enterprise_turns WHERE closed=1) AND e.sender!='agent' ORDER BY e.thread_id""")
deals = []
for r in rows:
    cid, g = r['customer_id'], r['group_id']
    if cid == 9692: deals.append([cid, [["B", 40.0]]])
    elif cid == 11361: deals.append([cid, [["B", 47.0]]])
    elif cid == 10603: deals.append([cid, [["A", 5.0], ["B", 12.0]]])
    elif g == 'E2': deals.append([cid, [["B", 55.0]]])
    elif g == 'E1': deals.append([cid, [["A", 9.0], ["B", 16.0]]])
    elif g == 'E3': deals.append([cid, [["B", 69.0]]])
    elif g == 'D_E09': deals.append([cid, [["A", 29.0], ["B", 59.0]]])
    else: print("UNHANDLED", r)
print("sending", len(deals), "deals")
do("ent_deals", lambda: nm.enterprise.send_enterprise_deal(deals))
do("capacity", lambda: nm.infrastructure.set_capacity_tier(4))
do("prices", lambda: nm.pricing.set_prices(A=25, B=115, C=185))
do("spend", lambda: nm.marketing.set_daily_spend(operations=4000, development=5000))
do("tdev", lambda: nm.analytics.set_targeted_dev_spend({"S2": 8000, "S3": 4000, "S1": 3000, "E2": 6000, "E1": 4000, "E3": 5000, "D_E09": 3000}))
ads = {"referral_program": {"S1": 500, "S3": 1200},
       "content_marketing": {"S1": 500, "S2": 9000},
       "social_media": {"S3": 300},
       "linkedin": {"S2": 2000}}
do("ads", lambda: nm.marketing.set_targeted_ad_spend(ads))
do("post", lambda: nm.marketing.post_social_media("Milestone: NovaMind now serves more than 12,000 professionals and our first enterprise teams. This week's model update raised answer accuracy and consistency again across every plan, and we doubled infrastructure capacity ahead of demand. Thank you for building with us."))
do("market_research", lambda: nm.market.research_market())
EOF
