import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:400])
    except Exception as e:
        print("ERR", label, "->", e)
def q(sql): return nm.query(sql)['rows']
rows = q("""SELECT e.thread_id, e.customer_id, e.turn_number, e.sender, e.offer_json, c.group_id
FROM enterprise_turns e JOIN customers c ON c.customer_id=e.customer_id
WHERE e.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)
AND e.thread_id NOT IN (SELECT thread_id FROM enterprise_turns WHERE closed=1) AND e.sender!='agent' ORDER BY e.thread_id""")
deals = []; counts = {}
for r in rows:
    cid, g = r['customer_id'], r['group_id']
    if r['sender'] == 'customer':
        try: p = float(json.loads(r['offer_json']).get('price'))
        except Exception: p = None
        if p is not None and p >= 3:
            deals.append([cid, [["B", p]]]); counts['counter_accept'] = counts.get('counter_accept',0)+1
        else:
            deals.append([cid, [["A", 4.0], ["B", 8.0]]]); counts['counter_low'] = counts.get('counter_low',0)+1
    elif g == 'E2': deals.append([cid, [["B", 49.0]]])
    elif g == 'E1': deals.append([cid, [["A", 8.0], ["B", 14.0]]])
    elif g == 'E3': deals.append([cid, [["B", 69.0]]])
    elif g == 'D_E09': deals.append([cid, [["A", 29.0], ["B", 59.0]]])
    else: print("UNHANDLED", r); continue
    counts[g] = counts.get(g,0)+1
print("deals:", len(deals), counts)
if deals:
    res = nm.enterprise.send_enterprise_deal(deals)
    ok = sum(1 for x in res.get('results',[]) if x.get('success'))
    print("sent ok:", ok, "of", len(res.get('results',[])), [x for x in res.get('results',[]) if not x.get('success')][:5])
do("prices", lambda: nm.pricing.set_prices(A=29, B=135, C=209))
do("spend", lambda: nm.marketing.set_daily_spend(operations=7000, development=8000))
do("tdev", lambda: nm.analytics.set_targeted_dev_spend({"S2": 10000, "S3": 5000, "S1": 4000, "E2": 8000, "E1": 5000, "E3": 6000, "D_E09": 4000}))
ads = {"referral_program": {"S1": 1000, "S3": 1800},
       "content_marketing": {"S1": 1000, "S2": 14000},
       "social_media": {"S3": 500},
       "linkedin": {"S2": 3000}}
do("ads", lambda: nm.marketing.set_targeted_ad_spend(ads))
do("post", lambda: nm.marketing.post_social_media("Reliability report, week 9: zero outages, P95 latency under 320ms at 3.8M daily requests, every support ticket resolved same day. We publish these numbers because enterprise buyers asked for them. Next up: SSO and regional data residency for team plans."))
do("market_research", lambda: nm.market.research_market())
