ids=json.load(open('notes/reneg_test_ids.json'))
q=lambda s: nm.query(s)['rows']
for r in q(f\"SELECT thread_type, sender, turn_number, closed, close_reason, COUNT(*) n FROM enterprise_turns WHERE customer_id IN ({','.join(map(str,ids))}) AND day>=112 GROUP BY thread_type, sender, turn_number, closed, close_reason\"): print(r)
for r in q(f\"SELECT customer_id, substr(message_text,1,200) m, offer_json FROM enterprise_turns WHERE customer_id IN ({','.join(map(str,ids))}) AND day>112 AND sender='customer' LIMIT 8\"): print(r)
for r in q(f\"SELECT customer_id, effective_price, status FROM subscriptions WHERE customer_id IN ({','.join(map(str,ids))}) ORDER BY effective_price DESC\"): print(r['customer_id'], r['effective_price'], r['status'], end=' | ')
" 2>&1 | grep -v '"request_id"'; echo; echo "=== ENT4 ==="; ./novamind-operation python scripts/ent4.py 2>&1 | grep -v '"request_id"' | grep -v "Counter-offer: Plan" | grep -v "churn_prevention', 't': 1" | tee notes/ent_day119.txt | sed -n '/### closed/,/### non-new/p' | grep -v "'n': 1}" | head -40

