import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:400])
    except Exception as e:
        print("ERR", label, "->", e)
do("promo", lambda: nm.pricing.set_promotion(global_promotion=0.0, by_group_plan={"S1": {"A": 30.0}, "S2": {"A": 12.0}, "D_S07": {"A": 30.0, "B": 60.0}, "D_S10": {"A": 30.0, "B": 60.0}}))
do("spend", lambda: nm.marketing.set_daily_spend(operations=36000, development=10000))
ads = {"referral_program": {"S1": 20000, "S3": 10000, "D_S07": 8000},
       "content_marketing": {"S1": 20000, "S2": 15000, "D_S10": 5000},
       "social_media": {"S3": 2000},
       "linkedin": {"D_S07": 4000, "D_S10": 5000}}
do("ads", lambda: nm.marketing.set_targeted_ad_spend(ads))
for i in range(3):
    do(f"market_research_{i}", lambda: nm.market.research_market())
do("post", lambda: nm.marketing.post_social_media("Two more research tracks shipped: multi-step agents and our self-checking evaluation pipeline are now live for all 900,000 seats. Independent benchmarks place NovaMind well ahead of the field. Loyal Pro customers now receive automatic tenure discounts. More to come."))

