import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:300])
    except Exception as e:
        print("ERR", label, "->", e)
do("promo", lambda: nm.pricing.set_promotion(global_promotion=0.0, by_group_plan={"S1": {"A": 45.0}, "S2": {"A": 30.0}, "S3": {"C": 40.0}, "D_S07": {"A": 35.0, "B": 70.0}, "D_S10": {"A": 40.0, "B": 70.0}, "D_S04": {"A": 30.0, "B": 80.0}, "D_S03": {"A": 50.0, "B": 100.0}, "D_S06": {"A": 35.0, "B": 110.0}, "D_S05": {"A": 35.0, "B": 100.0}}))
do("lead_promo", lambda: nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={"S1": 45.0, "D_S07": 60.0, "D_S10": 60.0, "D_S04": 70.0, "D_S03": 50.0, "D_S06": 50.0, "D_S05": 50.0}))
ads = {"referral_program": {"S1": 10000, "S3": 20000, "D_S07": 12000, "D_S05": 500},
       "content_marketing": {"S1": 15000, "S2": 1000, "D_S10": 5000, "D_S04": 3000},
       "social_media": {"S3": 5000, "D_S04": 3000, "D_S03": 6000},
       "linkedin": {"D_S07": 6000, "D_S10": 4000, "D_S03": 2000, "D_S06": 500}}
do("ads", lambda: nm.marketing.set_targeted_ad_spend(ads))
for i in range(3):
    do(f"market_research_{i}", lambda: nm.market.research_market())
do("post", lambda: nm.marketing.post_social_media("Support is back to same-day resolution: every ticket opened this week was closed the same day, at 47,000 tickets a day. Starter pricing is now permanently lower for individuals, and Power users get our top model tier at a loyalty rate. The new model generation lands in weeks."))

