import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:300])
    except Exception as e:
        print("ERR", label, "->", e)
do("quotas", lambda: nm.pricing.set_usage_quotas(A=150, B=400, C=1000))
ads = {"referral_program": {"S1": 3000, "S3": 12000, "D_S07": 10000, "D_S05": 3000},
       "content_marketing": {"S1": 5000, "S2": 1000, "D_S10": 1000, "D_S04": 12000},
       "social_media": {"S3": 2000, "D_S04": 12000, "D_S03": 20000},
       "linkedin": {"D_S07": 3000, "D_S10": 1000, "D_S03": 6000, "D_S06": 10000}}
do("ads", lambda: nm.marketing.set_targeted_ad_spend(ads))
for i in range(3):
    do(f"market_research_{i}", lambda: nm.market.research_market())
do("post", lambda: nm.marketing.post_social_media("Fine-tuning infrastructure is live: NovaMind now adapts to each team's documents and terminology automatically. 680,000 professionals and 1.1 million enterprise seats, same-day support held all week, cancellations down two-thirds. Next: our next-generation architecture."))

