import novamind_api as nm, json
def do(label, fn):
    try:
        r = fn(); print("OK", label, "->", json.dumps(r, default=str)[:300])
    except Exception as e:
        print("ERR", label, "->", e)
do("lead_promo_zero", lambda: nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={"S1": 0.0, "D_S07": 0.0, "D_S10": 0.0, "D_S04": 0.0, "D_S03": 0.0, "D_S06": 0.0, "D_S05": 0.0, "D_S08": 0.0}))
