do("quotas", lambda: nm.pricing.set_usage_quotas(A=150, B=400, C=1000))
do("spend", lambda: nm.marketing.set_daily_spend(operations=120000, development=5000))
do("tdev", lambda: nm.analytics.set_targeted_dev_spend({"S1": 2000, "S2": 1000, "S3": 2000, "E1": 1000, "E2": 1000, "E3": 2000, "D_E09": 2000, "D_E02": 3000, "D_E08": 3000, "D_E07": 4000, "D_S07": 2000, "D_S10": 1000, "D_S04": 2000, "D_S03": 3000, "D_S06": 3000, "D_S05": 3000, "D_E01": 5000, "D_E03": 5000, "D_E10": 4000, "D_E05": 6000, "D_S08": 4000}))
